// Normaliza a mensagem do WhatsApp (Evolution v2): grupo=invalida, extrai telefone/texto/mid
// e a mídia (áudio/imagem/documento/vídeo → URL do Evolution) para o cérebro Edge
const evt = $json.body ?? {};
const data = evt.data ?? {};
const remoteJid = String(data.key?.remoteJid ?? '');
const isGroup = remoteJid.endsWith('@g.us');
const phone = remoteJid.replace(/@s\.whatsapp\.net|@g\.us/g, '').replace(/\D/g, '');
const msg = data.message ?? {};
let text = String(msg.conversation ?? msg.extendedTextMessage?.text ?? '').trim();
let media = null;
const kindFor = (m) => {
  if (m?.audioMessage?.url) return { kind: 'audio', url: String(m.audioMessage.url) };
  if (m?.imageMessage?.url) return { kind: 'image', url: String(m.imageMessage.url) };
  if (m?.documentMessage?.url) return { kind: 'document', url: String(m.documentMessage.url) };
  if (m?.videoMessage?.url) return { kind: 'video', url: String(m.videoMessage.url) };
  return null;
};
for (const k of Object.keys(msg)) {
  const m = kindFor(msg[k] ?? {});
  if (m) { media = m; break; }
}
text = text || String(msg.imageMessage?.caption ?? msg.documentMessage?.caption ?? msg.videoMessage?.caption ?? '').trim();
return [{ json: { isGroup, phone, text, media, mid: String(data.key?.id ?? ''), instance: String(evt.instance ?? ''), pushName: String(data.pushName ?? '') } };]

// Monta o payload do cérebro + o timestamp para a assinatura (janela 5min)
const n = $('Normalizar Mensagem').first().json;
const environment = String(n.instance ?? '').toLowerCase().includes('estrategos') ? 'estrategos' : 'sharks_company';
const payload = {
  action: 'reply',
  environment,
  channel: 'whatsapp',
  contact: { phone: n.phone },
  text: n.text || '',
  mid: n.mid || '',
  ...(n.media ? { media: n.media } : {}),
};
const payloadStr = JSON.stringify(payload);
return [{ json: { ts: Math.floor(Date.now() / 1000), payloadStr } }];

// Prepara o envio da resposta conforme o cerebro (JSON estruturado):
const brain = $json;
if (!brain.ok || brain.mode === 'human' || brain.action === 'skip') {
  return [{ json: { skip: true, lead_id: brain.lead_id ?? null, reason: brain.error ?? 'modo humano/sem cerebro' } }];
}
if (!brain.reply && !brain.media_url && !brain.audio_url) { throw new Error('Sem resposta do cerebro'); }
const webhook = $('Evolution Webhook').first().json;
const data = webhook.data ?? {};
const number = String(data.key?.remoteJid ?? '').replace(/@s\.whatsapp\.net|@g\.us/g, '').replace(/\D/g, '');
if (brain.media_url) {
  const res = await fetch(String(brain.media_url));
  if (res.ok) {
    const buf = Buffer.from(await res.arrayBuffer());
    const ext = (String(brain.media_url).split('?')[0].split('.').pop() ?? '').toLowerCase();
    const isImage = ['png','jpg','jpeg','webp'].includes(ext);
    const mime = isImage ? 'image/' + (ext === 'jpeg' ? 'jpeg' : ext) : 'application/pdf';
    return [{ json: { number, mode: 'media', mediatype: isImage ? 'image' : 'document', mimeType: mime, media: 'data:' + mime + ';base64,' + buf.toString('base64'), reply: String(brain.reply ?? ''), lead_id: brain.lead_id } }];
  }
  console.error('[preparar] media falhou:', res.status);
}
if (brain.audio_url) {
  const res = await fetch(String(brain.audio_url));
  if (res.ok) {
    const buf = Buffer.from(await res.arrayBuffer());
    return [{ json: { number, mode: 'audio', audio: 'data:audio/mpeg;base64,' + buf.toString('base64'), reply: String(brain.reply ?? ''), lead_id: brain.lead_id } }];
  }
}
return [{ json: { number, mode: 'text', reply: String(brain.reply ?? ''), lead_id: brain.lead_id } }];

// Payload do registro de envio + timestamp p/ assinatura
const env = $('Cerebro da Conversa (Edge)').first().json.environment ?? 'sharks_company';
const payload = {
  action: 'sent',
  environment: String(env).includes('estrategos') ? 'estrategos' : 'sharks_company',
  lead_id: $('Preparar Resposta').first().json.lead_id,
  text: $('Preparar Resposta').first().json.reply ?? '',
};
const payloadStr = JSON.stringify(payload);
return [{ json: { ts: Math.floor(Date.now() / 1000), payloadStr } }];

// Payload de erro + ts
const payload = { action: 'error', environment: 'sharks_company', text: 'Falha no fluxo de conversa: ' + ($json.error ?? 'erro desconhecido') };
const payloadStr = JSON.stringify(payload);
return [{ json: { ts: Math.floor(Date.now() / 1000), payloadStr } }];
